var t=`1004-red-curry`;var n=`world-1004`;var s=`TH`;var a=`southeast-asia`;var r=4;var d=32;var h={en:`Red Curry`,ua:`Червоне карі`};var o={en:`Red Curry is a dish from Thailand prepared with thai red curry paste, coconut cream, chicken breast, coconut milk. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Червоне карі, страва кухні країни Таїланд, яку готують із таких продуктів: червона тайська паста карі, кокосові вершки, куряча грудка, кокосове молоко. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var u=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 5 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 5 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:5,i:[[`thai-red-curry-paste`,85,`g`],[`coconut-cream`,170,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 22 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 22 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:22,i:[[`chicken-breast`,650,`g`],[`coconut-milk`,470,`ml`],[`red-bell-pepper`,200,`g`],[`bamboo-shoots`,170,`g`]]},{en:`Stir in these seasonings and additions. Taste, adjust the balance and let the dish stand briefly before serving.`,ua:`Додайте приправи та завершальні складники. Спробуйте, збалансуйте смак і дайте страві трохи настоятися перед подаванням.`,t:[`seasoning`,`finishing-with-herbs`],m:3,i:[[`fish-sauce`,40,`ml`],[`palm-sugar`,20,`g`],[`makrut-lime-leaves`,4,`leaf`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`thai-basil`,20,`g`]]}];var l={slug:t,id:n,country:`TH`,region:a,servings:4,minutes:32,title:h,text:o,steps:u};export{s as country,l as default,n as id,d as minutes,a as region,r as servings,t as slug,u as steps,o as text,h as title};